macro_rules! deps {
    () => {
        AnalysisAndResults!();
        Forward!();
        Direction!();
        DebugWithContext!();
        Backward!();
        JoinSemiLattice!();
    };
}

macro_rules! Analysis {
    () => {
        deps!();
        # [doc = " A dataflow problem with an arbitrarily complex transfer function."] # [doc = ""] # [doc = " This trait specifies the lattice on which this analysis operates (the domain), its"] # [doc = " initial value at the entry point of each basic block, and various operations."] # [doc = ""] # [doc = " # Convergence"] # [doc = ""] # [doc = " When implementing this trait it's possible to choose a transfer function such that the analysis"] # [doc = " does not reach fixpoint. To guarantee convergence, your transfer functions must maintain the"] # [doc = " following invariant:"] # [doc = ""] # [doc = " > If the dataflow state **before** some point in the program changes to be greater"] # [doc = " than the prior state **before** that point, the dataflow state **after** that point must"] # [doc = " also change to be greater than the prior state **after** that point."] # [doc = ""] # [doc = " This invariant guarantees that the dataflow state at a given point in the program increases"] # [doc = " monotonically until fixpoint is reached. Note that this monotonicity requirement only applies"] # [doc = " to the same point in the program at different points in time. The dataflow state at a given"] # [doc = " point in the program may or may not be greater than the state at any preceding point."] pub trait Analysis < 'tcx > { # [doc = " The type that holds the dataflow state at any given point in the program."] type Domain : Clone + JoinSemiLattice ; # [doc = " The direction of this analysis. Either `Forward` or `Backward`."] type Direction : Direction = Forward ; # [doc = " Auxiliary data used for analyzing `SwitchInt` terminators, if necessary."] type SwitchIntData = ! ; # [doc = " A descriptive name for this analysis. Used only for debugging."] # [doc = ""] # [doc = " This name should be brief and contain no spaces, periods or other characters that are not"] # [doc = " suitable as part of a filename."] const NAME : & 'static str ; # [doc = " Returns the initial value of the dataflow state upon entry to each basic block."] fn bottom_value (& self , body : & mir :: Body < 'tcx >) -> Self :: Domain ; # [doc = " Mutates the initial value of the dataflow state upon entry to the `START_BLOCK`."] # [doc = ""] # [doc = " For backward analyses, initial state (besides the bottom value) is not yet supported. Trying"] # [doc = " to mutate the initial state will result in a panic."] fn initialize_start_block (& self , body : & mir :: Body < 'tcx > , state : & mut Self :: Domain) ; # [doc = " Updates the current dataflow state with an \"early\" effect, i.e. one"] # [doc = " that occurs immediately before the given statement."] # [doc = ""] # [doc = " This method is useful if the consumer of the results of this analysis only needs to observe"] # [doc = " *part* of the effect of a statement (e.g. for two-phase borrows). As a general rule,"] # [doc = " analyses should not implement this without also implementing"] # [doc = " `apply_primary_statement_effect`."] fn apply_early_statement_effect (& mut self , _state : & mut Self :: Domain , _statement : & mir :: Statement < 'tcx > , _location : Location ,) { } # [doc = " Updates the current dataflow state with the effect of evaluating a statement."] fn apply_primary_statement_effect (& mut self , state : & mut Self :: Domain , statement : & mir :: Statement < 'tcx > , location : Location ,) ; # [doc = " Updates the current dataflow state with an effect that occurs immediately *before* the"] # [doc = " given terminator."] # [doc = ""] # [doc = " This method is useful if the consumer of the results of this analysis needs only to observe"] # [doc = " *part* of the effect of a terminator (e.g. for two-phase borrows). As a general rule,"] # [doc = " analyses should not implement this without also implementing"] # [doc = " `apply_primary_terminator_effect`."] fn apply_early_terminator_effect (& mut self , _state : & mut Self :: Domain , _terminator : & mir :: Terminator < 'tcx > , _location : Location ,) { } # [doc = " Updates the current dataflow state with the effect of evaluating a terminator."] # [doc = ""] # [doc = " The effect of a successful return from a `Call` terminator should **not** be accounted for"] # [doc = " in this function. That should go in `apply_call_return_effect`. For example, in the"] # [doc = " `InitializedPlaces` analyses, the return place for a function call is not marked as"] # [doc = " initialized here."] fn apply_primary_terminator_effect < 'mir > (& mut self , _state : & mut Self :: Domain , terminator : & 'mir mir :: Terminator < 'tcx > , _location : Location ,) -> TerminatorEdges < 'mir , 'tcx > { terminator . edges () } # [doc = " Updates the current dataflow state with the effect of a successful return from a `Call`"] # [doc = " terminator."] # [doc = ""] # [doc = " This is separate from `apply_primary_terminator_effect` to properly track state across"] # [doc = " unwind edges."] fn apply_call_return_effect (& mut self , _state : & mut Self :: Domain , _block : BasicBlock , _return_places : CallReturnPlaces < '_ , 'tcx > ,) { } # [doc = " Used to update the current dataflow state with the effect of taking a particular branch in"] # [doc = " a `SwitchInt` terminator."] # [doc = ""] # [doc = " Unlike the other edge-specific effects, which are allowed to mutate `Self::Domain`"] # [doc = " directly, overriders of this method must return a `Self::SwitchIntData` value (wrapped in"] # [doc = " `Some`). The `apply_switch_int_edge_effect` method will then be called once for each"] # [doc = " outgoing edge and will have access to the dataflow state that will be propagated along that"] # [doc = " edge, and also the `Self::SwitchIntData` value."] # [doc = ""] # [doc = " This interface is somewhat more complex than the other visitor-like \"effect\" methods."] # [doc = " However, it is both more ergonomic—callers don't need to recompute or cache information"] # [doc = " about a given `SwitchInt` terminator for each one of its edges—and more efficient—the"] # [doc = " engine doesn't need to clone the exit state for a block unless"] # [doc = " `get_switch_int_data` is actually called."] fn get_switch_int_data (& mut self , _block : mir :: BasicBlock , _discr : & mir :: Operand < 'tcx > ,) -> Option < Self :: SwitchIntData > { None } # [doc = " See comments on `get_switch_int_data`."] fn apply_switch_int_edge_effect (& mut self , _data : & mut Self :: SwitchIntData , _state : & mut Self :: Domain , _value : SwitchTargetValue , _targets : & mir :: SwitchTargets ,) { unreachable ! () ; } # [doc = " Finds the fixpoint for this dataflow problem."] # [doc = ""] # [doc = " You shouldn't need to override this. Its purpose is to enable method chaining like so:"] # [doc = ""] # [doc = " ```ignore (cross-crate-imports)"] # [doc = " let results = MyAnalysis::new(tcx, body)"] # [doc = "     .iterate_to_fixpoint(tcx, body, None)"] # [doc = "     .into_results_cursor(body);"] # [doc = " ```"] # [doc = " You can optionally add a `pass_name` to the graphviz output for this particular run of a"] # [doc = " dataflow analysis. Some analyses are run multiple times in the compilation pipeline."] # [doc = " Without a `pass_name` to differentiates them, only the results for the latest run will be"] # [doc = " saved."] fn iterate_to_fixpoint < 'mir > (mut self , tcx : TyCtxt < 'tcx > , body : & 'mir mir :: Body < 'tcx > , pass_name : Option < & 'static str > ,) -> AnalysisAndResults < 'tcx , Self > where Self : Sized , Self :: Domain : DebugWithContext < Self > , { let mut results = IndexVec :: from_fn_n (| _ | self . bottom_value (body) , body . basic_blocks . len ()) ; self . initialize_start_block (body , & mut results [mir :: START_BLOCK]) ; if Self :: Direction :: IS_BACKWARD && results [mir :: START_BLOCK] != self . bottom_value (body) { bug ! ("`initialize_start_block` is not yet supported for backward dataflow analyses") ; } let mut dirty_queue : WorkQueue < BasicBlock > = WorkQueue :: with_none (body . basic_blocks . len ()) ; if Self :: Direction :: IS_FORWARD { for (bb , _) in traversal :: reverse_postorder (body) { dirty_queue . insert (bb) ; } } else { for (bb , _) in traversal :: postorder (body) { dirty_queue . insert (bb) ; } } let mut state = self . bottom_value (body) ; while let Some (bb) = dirty_queue . pop () { state . clone_from (& results [bb]) ; Self :: Direction :: apply_effects_in_block (& mut self , body , & mut state , bb , & body [bb] , | target : BasicBlock , state : & Self :: Domain | { let set_changed = results [target] . join (state) ; if set_changed { dirty_queue . insert (target) ; } } ,) ; } if tcx . sess . opts . unstable_opts . dump_mir_dataflow { let res = write_graphviz_results (tcx , body , & mut self , & results , pass_name) ; if let Err (e) = res { error ! ("Failed to write graphviz dataflow results: {}" , e) ; } } AnalysisAndResults { analysis : self , results } } }
    };
}

Analysis!();